;(() => {
  // Ground crawl against a supersampled truth (walking, eye height), per distance band.
  const W = 1632, H = 918, F = (H / 2) / Math.tan((35 * Math.PI) / 180), EYE = 1.7, SS = 2;
  const cv = document.createElement("canvas");
  const c2 = cv.getContext("2d", { willReadFrequently: true });
  const grab = (w, h) => {
    const el = window.brDraw(w, h);
    cv.width = w; cv.height = h;
    c2.drawImage(el, 0, 0, w, h);
    const d = c2.getImageData(0, 0, w, h).data, out = new Float32Array(w * h);
    for (let i = 0, j = 0; i < out.length; i++, j += 4) out[i] = 0.299 * d[j] + 0.587 * d[j + 1] + 0.114 * d[j + 2];
    return out;
  };
  const down = (big) => {
    const out = new Float32Array(W * H), BW = W * SS;
    for (let y = 0; y < H; y++)
      for (let x = 0; x < W; x++) {
        let s = 0;
        for (let a = 0; a < SS; a++) for (let b = 0; b < SS; b++) s += big[(y * SS + a) * BW + x * SS + b];
        out[y * W + x] = s / (SS * SS);
      }
    return out;
  };
  const BANDS = [[4, 7], [7, 12], [12, 20], [20, 35], [35, 55], [55, 80], [80, 120]];
  const rows = ([a, b]) => [Math.round(H / 2 + (F * EYE) / b), Math.round(H / 2 + (F * EYE) / a)];
  window.brCrawlShots = [];
  // views: { name: [x, z, headingDeg, x0, x1] }; variants: [[name, setup()]]; truth: setup for the reference
  window.brCrawl = async (views, variants, truth, opts = {}) => {
    const ex = window.explorer, steps = opts.steps ?? 6, step = opts.step ?? 0.11;
    const out = {};
    for (const [vn, [x, z, hd, x0 = 0.3, x1 = 0.7]] of Object.entries(views)) {
      const dx = Math.sin((hd * Math.PI) / 180), dz = -Math.cos((hd * Math.PI) / 180);
      const c0 = Math.round(x0 * W), c1 = Math.round(x1 * W);
      const at = async (k) => {
        const px = x + dx * step * k, pz = z + dz * step * k, y = ex.groundAt(px, pz) + EYE;
        await ex.view([px, y, pz], [px + dx * 100, y - 0.0, pz + dz * 100], { near: 0.1, fov: 70 });
      };
      // The truth: SS × SS supersampled, with `truth` set.
      const ref = [];
      truth();
      for (let k = 0; k < steps; k++) { await at(k); ref.push(down(grab(W * SS, H * SS))); }
      out[vn] = {};
      for (const [name, setup] of variants) {
        setup();
        const frames = [];
        for (let k = 0; k < steps; k++) {
          await at(k);
          frames.push(grab(W, H));
          if (k === 0) {
            const shot = document.createElement("canvas");
            shot.width = 816; shot.height = 200;
            shot.getContext("2d").drawImage(window.brDraw(W, H), W / 2 - 408, H / 2 + 20, 816, 200, 0, 0, 816, 200);
            window.brCrawlShots.push([`${vn} ${name}`, shot]);
          }
        }
        const res = {};
        for (const band of BANDS) {
          const [r0, r1] = rows(band);
          let detail = 0, n = 0, err = 0, crawl = 0, tdet = 0, m = 0;
          for (let r = Math.max(0, r0); r <= Math.min(H - 1, r1); r++)
            for (let c = c0; c < c1; c++) {
              const i = r * W + c;
              detail += Math.abs(frames[0][i + 1] - frames[0][i]);
              tdet += Math.abs(ref[0][i + 1] - ref[0][i]);
              err += Math.abs(frames[0][i] - ref[0][i]);
              n++;
              for (let k = 1; k < steps; k++) {
                crawl += Math.abs((frames[k][i] - ref[k][i]) - (frames[k - 1][i] - ref[k - 1][i]));
                m++;
              }
            }
          res[`${band[0]}-${band[1]}`] = { detail: +(detail / n).toFixed(2), truth: +(tdet / n).toFixed(2), err: +(err / n).toFixed(2), crawl: +(crawl / m).toFixed(2) };
        }
        out[vn][name] = res;
      }
    }
    return out;
  };
  window.brCrawlShow = () => {
    let host = document.getElementById("lab-shots");
    if (!host) {
      host = document.createElement("div");
      host.id = "lab-shots";
      host.style.cssText = "position:fixed;inset:0;z-index:99999;background:#111;overflow:auto;font:12px monospace;color:#fff";
      document.body.appendChild(host);
    }
    host.innerHTML = "";
    for (const [label, shot] of window.brCrawlShots) {
      const p = document.createElement("div");
      p.textContent = label;
      host.appendChild(p);
      shot.style.cssText = "display:block;width:816px;height:200px";
      host.appendChild(shot);
    }
  };
})();
